public int[][] UpdateMatrix(int[][] mat) {
    int rows = mat.Length, cols = mat[0].Length;
    var dist = new int[rows][];
    var queue = new Queue<(int r, int c)>();
    for (int r = 0; r < rows; r++) {
        dist[r] = new int[cols];
        for (int c = 0; c < cols; c++) {
            if (mat[r][c] == 0) queue.Enqueue((r, c));   // каждый 0 — источник
            else dist[r][c] = -1;                        // ещё не дошли
        }
    }
    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    while (queue.Count > 0) {
        var (r, c) = queue.Dequeue();
        for (int d = 0; d < 4; d++) {
            int y = r + dr[d], x = c + dc[d];
            if (y < 0 || x < 0 || y >= rows || x >= cols || dist[y][x] != -1) continue;
            dist[y][x] = dist[r][c] + 1;                 // первая волна — ближайшая
            queue.Enqueue((y, x));
        }
    }
    return dist;
}

