// шаги до ближайшего выхода — один BFS на всех агентов
void BuildDistance(bool[] open, int w, int h, int[] exits, int[] dist, int[] queue) {
    Array.Fill(dist, -1);
    int head = 0, tail = 0;
    foreach (int e in exits) { dist[e] = 0; queue[tail++] = e; }
    while (head < tail) {
        int i = queue[head++], x = i % w, d = dist[i] + 1;
        if (x > 0 && open[i - 1] && dist[i - 1] < 0) { dist[i - 1] = d; queue[tail++] = i - 1; }
        if (x < w - 1 && open[i + 1] && dist[i + 1] < 0) { dist[i + 1] = d; queue[tail++] = i + 1; }
        if (i >= w && open[i - w] && dist[i - w] < 0) { dist[i - w] = d; queue[tail++] = i - w; }
        if (i + w < w * h && open[i + w] && dist[i + w] < 0) { dist[i + w] = d; queue[tail++] = i + w; }
    }
}
// агент в клетке i шагает к соседу, у которого dist == dist[i] - 1
